#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Smoke test helpers. These sit below the marker because they are specific
# to this wizard.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_DIR="$(cd "$SCRIPT_DIR/../.." && pwd)"
MESSAGES="$SCRIPT_DIR/messages"
GO="${GO:-go}"
SMTP_PORT="${SMTP_PORT:-2525}"
DENY_PORT="${DENY_PORT:-2526}"
METRICS_PORT="${METRICS_PORT:-9925}"
RUN_DIR=""
TAG=""
RESULTS=()
PIDS=()

# record ID RESULT NOTE adds a line to the results summary.
record() {
  RESULTS+=("$(printf '%-4s %-4s %s' "$1" "$2" "$3")")
  printf '%s %s %s\n' "$1" "$2" "$3" >> "$RUN_DIR/results.txt"
  case "$2" in
    PASS) printf '  %s✓ %s passed%s %s\n' "$GREEN" "$1" "$RESET" "$3" ;;
    SKIP) note "$1 skipped: $3" ;;
    *)    warn "$1 failed: $3" ;;
  esac
}

# check ID "question" asks the human to confirm what they see in the mailbox.
check() {
  if confirm "$2"; then record "$1" PASS ""; else record "$1" FAIL "not as expected in the mailbox"; fi
}

# render FILE [TO] writes a message template with this run's addresses and
# tag filled in, and prints the path of the result. __TO__ is recipient A
# unless TO is given.
render() {
  local out="$RUN_DIR/$(basename "$1")"
  sed -e "s|__FROM__|${MAIL_FROM}|g" -e "s|__TO_B__|${RCPT_B}|g" \
      -e "s|__TO__|${2:-$RCPT_A}|g" -e "s|__TAG__|${TAG}|g" "$1" > "$out"
  printf '%s' "$out"
}

# send PORT FROM FILE RCPT... sends FILE with curl, logging the SMTP
# conversation to $RUN_DIR/curl.log. Succeeds when the message is accepted.
send() {
  local port="$1" from="$2" file="$3"; shift 3
  local args=() r
  for r in "$@"; do args+=(--mail-rcpt "$r"); done
  printf '\n=== %s from %s to %s\n' "$(basename "$file")" "$from" "$*" >> "$RUN_DIR/curl.log"
  curl -sS -v --crlf --max-time 120 --url "smtp://127.0.0.1:${port}" \
    --mail-from "$from" "${args[@]}" --upload-file "$file" >> "$RUN_DIR/curl.log" 2>&1
}

# last_reply prints the reply code that ended the most recent send: its first
# error reply, or its last reply if there was no error.
last_reply() {
  awk '/^=== /{ code = ""; err = "" }
       /^< [0-9][0-9][0-9]/{ code = substr($0, 3, 3); if (err == "" && code >= 400) err = code }
       END { print (err != "" ? err : code) }' "$RUN_DIR/curl.log"
}

# send_case ID FILE RCPT... sends a message that should be accepted.
send_case() {
  local id="$1" file="$2"; shift 2
  if send "$SMTP_PORT" "$MAIL_FROM" "$file" "$@"; then
    printf '  %s✓ accepted by graph-smtpd%s\n' "$GREEN" "$RESET"
    return 0
  fi
  record "$id" FAIL "not accepted (reply $(last_reply)); see $RUN_DIR/curl.log and smtpd.log"
  return 1
}

# expect_reply ID CODE PORT FROM FILE RCPT... sends a message that should be
# refused with CODE.
expect_reply() {
  local id="$1" code="$2" port="$3" from="$4" file="$5" got; shift 5
  if send "$port" "$from" "$file" "$@"; then
    record "$id" FAIL "accepted, expected $code"
    return
  fi
  got=$(last_reply)
  if [[ "$got" == "$code" ]]; then record "$id" PASS "refused with $got"
  else record "$id" FAIL "refused with $got, expected $code"; fi
}

# start_smtpd PORT LOG ARGS... starts graph-smtpd in the background and waits
# for it to listen.
start_smtpd() {
  local port="$1" log="$2" i; shift 2
  env -u SMTPD_SECRET SMTPD_TENANTID="$TENANT_ID" SMTPD_CLIENTID="$CLIENT_ID" SMTPD_SECRET_FILE="$SECRET_FILE" \
    "$RUN_DIR/graph-smtpd" --addr "127.0.0.1:${port}" --domain smoke-test.local --debug "$@" \
    > "$log" 2>&1 &
  PIDS+=("$!")
  for i in $(seq 1 50); do
    if (exec 3<>"/dev/tcp/127.0.0.1/${port}") 2>/dev/null; then return 0; fi
    kill -0 "$!" 2>/dev/null || break
    sleep 0.2
  done
  warn "graph-smtpd did not start; last lines of $log:"
  tail -n 5 "$log" | sed 's/^/    /'
  return 1
}

# smtp_reply reads one SMTP reply from fd 3 into REPLY_CODE.
smtp_reply() {
  local line
  while IFS= read -r -t 120 line <&3; do
    line="${line%$'\r'}"
    printf '< %s\n' "$line" >> "$RUN_DIR/session.log"
    [[ "${line:3:1}" == " " ]] && break
  done
  REPLY_CODE="${line:0:3}"
}

# smtp CMD EXPECT sends one command on fd 3 and checks the reply code.
smtp() {
  printf '> %s\n' "$1" >> "$RUN_DIR/session.log"
  printf '%s\r\n' "$1" >&3
  smtp_reply
  [[ "$REPLY_CODE" == "$2" ]]
}

# smtp_message FROM RCPT FILE sends one message on the open fd 3 session.
smtp_message() {
  smtp "MAIL FROM:<$1>" 250 && smtp "RCPT TO:<$2>" 250 && smtp "DATA" 354 || return 1
  sed -e 's/\r$//' -e 's/^\./../' -e 's/$/\r/' "$3" >&3
  smtp "." 250
}

# metric NAME prints the value of a counter from graph-smtpd's /metrics.
metric() {
  curl -sS "http://127.0.0.1:${METRICS_PORT}/metrics" | awk -v n="$1" '$1 == n { print $2 }'
}

cleanup() {
  local pid
  for pid in "${PIDS[@]}"; do kill "$pid" 2>/dev/null || true; done
}

run_wizard() {

TOTAL_STAGES=18

banner "graph-smtpd smoke test"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tenant details"
say "These tests send real email through your Microsoft 365 tenant, using the"
say "same Entra ID app registration graph-smtpd uses in production."
note "Nothing you enter here is saved. The secret is read from a file you name,"
note "so it is never typed into this script."
printf '\n'
ask TENANT_ID "Tenant ID:"
ask CLIENT_ID "Client (application) ID:"
ask SECRET_FILE "Path to a file containing the client secret:"
SECRET_FILE="${SECRET_FILE/#\~/$HOME}"
if [[ ! -r "$SECRET_FILE" ]]; then
  warn "can't read $SECRET_FILE"; exit 1
fi
SECRET_FILE="$(cd "$(dirname "$SECRET_FILE")" && pwd)/$(basename "$SECRET_FILE")"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Mailboxes"
say "You need a mailbox the app may send as, and two mailboxes you can read."
note "Plus addressing (you+a@domain, you+b@domain) is fine for A and B, but use"
note "a separate mail client view for each so you can tell which copy arrived."
printf '\n'
ask MAIL_FROM "Sender mailbox (the app may send as this):"
ask RCPT_A "Recipient A:"
ask RCPT_B "Recipient B (must differ from A):"
say ""
say "Optional: a real mailbox in your tenant that the app is NOT allowed to"
say "send as (outside your ApplicationAccessPolicy). Leave blank to skip S11."
ask DENIED_BY_GRAPH "Mailbox the app may not send as [blank to skip]:" || DENIED_BY_GRAPH=""
if [[ "$RCPT_A" == "$RCPT_B" ]]; then warn "A and B must differ"; exit 1; fi
DOMAIN="${MAIL_FROM#*@}"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Build"
RUN_DIR="$(mktemp -d "${TMPDIR:-/tmp}/graph-smtpd-smoke.XXXXXX")"
TAG="smoke-$(date +%Y%m%d-%H%M%S)"
trap cleanup EXIT
say "Building graph-smtpd and graph-sendmail from $REPO_DIR"
note "commit $(git -C "$REPO_DIR" rev-parse --short HEAD 2>/dev/null || echo unknown)"
(cd "$REPO_DIR" && "$GO" build -o "$RUN_DIR/" ./cmd/graph-smtpd ./cmd/graph-sendmail)
printf '  %s✓ built%s into %s\n' "$GREEN" "$RESET" "$RUN_DIR"
say ""
say "Every message this run sends has this tag in its subject:"
printf '\n      %s%s%s\n\n' "$BOLD" "$TAG" "$RESET"
say "Search for it in both mailboxes as you go."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Start graph-smtpd (S12)"
say "Starting graph-smtpd on 127.0.0.1:${SMTP_PORT}, reading the secret from"
say "SMTPD_SECRET_FILE, allowing only 127.0.0.1 and your sender."
SENDERS="$MAIL_FROM"
[[ -n "$DENIED_BY_GRAPH" ]] && SENDERS="$SENDERS,$DENIED_BY_GRAPH"
if start_smtpd "$SMTP_PORT" "$RUN_DIR/smtpd.log" \
  --sources 127.0.0.1 --senders "$SENDERS" --metrics "127.0.0.1:${METRICS_PORT}"; then
  printf '  %s✓ listening%s\n' "$GREEN" "$RESET"
  note "S12 passes once a message is delivered below, since that proves the secret file was used."
else
  record S12 FAIL "graph-smtpd did not start"
  finish; exit 1
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "S1 · plain text"
if send_case S1 "$(render "$MESSAGES/s1-plain.eml")" "$RCPT_A"; then
  record S12 PASS "started and delivered using SMTPD_SECRET_FILE"
  step "In mailbox A, open \"[$TAG] S1 plain text\"."
  check S1 "Did it arrive, with the body text intact?"
  say ""
  step "View that message's headers (Outlook: File → Properties, or View message source)."
  say "Look for: Message-ID: <$TAG.s1@smoke-test.local>"
  check S15 "Does the Message-ID header match exactly?"
else
  record S12 FAIL "first send failed; check the secret and permissions in smtpd.log"
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "S2 · text and HTML"
if send_case S2 "$(render "$MESSAGES/s2-alternative.eml")" "$RCPT_A"; then
  step "In mailbox A, open \"[$TAG] S2 text and HTML\"."
  check S2 "Does it show the HTML part (bold start, red word), not the plain text part?"
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "S3 · inline image"
if send_case S3 "$(render "$MESSAGES/s3-inline.eml")" "$RCPT_A"; then
  step "In mailbox A, open \"[$TAG] S3 inline image\"."
  note "Your client may block images until you allow them."
  check S3 "Is a red and blue checkerboard shown inside the body (not only as an attachment)?"
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "S4 · attachments"
if send_case S4 "$(render "$MESSAGES/s4-attachments.eml")" "$RCPT_A"; then
  step "In mailbox A, open \"[$TAG] S4 attachments\" and open each attachment."
  say "  base64.txt     → attachment encoded as base64"
  say "  qp.txt         → café attachment encoded as quoted-printable"
  say "  unencoded.txt  → attachment with no transfer encoding"
  check S4 "Are all three there, each with exactly that text (none empty)?"
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "S5 · Windows-1252 text"
if send_case S5 "$(render "$MESSAGES/s5-charset.eml")" "$RCPT_A"; then
  step "In mailbox A, open \"[$TAG] S5 café charset\"."
  say "Expected subject: [$TAG] S5 café charset"
  say "Expected body line: café “curly quotes” €uro"
  check S5 "Do the subject and body show é, curly quotes and € correctly?"
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "S6 · envelope-only Bcc"
if send_case S6 "$(render "$MESSAGES/s6-envelope-bcc.eml")" "$RCPT_A" "$RCPT_B"; then
  step "Find \"[$TAG] S6 envelope-only Bcc\" in BOTH mailboxes."
  check S6 "Did both A and B receive it, with B's address not shown in To or Cc on A's copy?"
fi
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "S7 · header-only recipient"
if send_case S7 "$(render "$MESSAGES/s7-header-only.eml")" "$RCPT_A"; then
  step "Find \"[$TAG] S7 header-only recipient\"."
  note "Give B a minute: you are checking that it does NOT arrive there."
  check S7 "Did A receive it, and B NOT receive it?"
fi
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "S8 · two messages on one connection"
say "Sending two messages over a single SMTP session: the first to A, the"
say "second to B."
: > "$RUN_DIR/session.log"
if exec 3<>"/dev/tcp/127.0.0.1/${SMTP_PORT}" && smtp_reply && [[ "$REPLY_CODE" == 220 ]] \
  && smtp "EHLO smoke-test.local" 250 \
  && smtp_message "$MAIL_FROM" "$RCPT_A" "$(render "$MESSAGES/s8-first.eml")" \
  && smtp_message "$MAIL_FROM" "$RCPT_B" "$(render "$MESSAGES/s8-second.eml" "$RCPT_B")"; then
  smtp "QUIT" 221 || true
  exec 3>&-
  printf '  %s✓ both accepted%s\n' "$GREEN" "$RESET"
  step "Find the two \"[$TAG] S8\" messages."
  check S8 "Did A get only the first, and B get only the second?"
else
  exec 3>&-
  record S8 FAIL "session failed with reply ${REPLY_CODE:-none}; see $RUN_DIR/session.log"
fi
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "S9 · sender not allowed"
say "Sending as smoke-not-allowed@${DOMAIN}, which is not in --senders."
expect_reply S9 550 "$SMTP_PORT" "smoke-not-allowed@${DOMAIN}" \
  "$(render "$MESSAGES/s1-plain.eml")" "$RCPT_A"
pause

# ── 14 ────────────────────────────────────────────────────────────────────
stage "S10 · source not allowed"
say "Starting a second graph-smtpd on port ${DENY_PORT} that only allows"
say "192.0.2.1, so this machine is refused."
if start_smtpd "$DENY_PORT" "$RUN_DIR/smtpd-denied.log" --sources 192.0.2.1; then
  expect_reply S10 550 "$DENY_PORT" "$MAIL_FROM" "$(render "$MESSAGES/s1-plain.eml")" "$RCPT_A"
else
  record S10 FAIL "second graph-smtpd did not start"
fi
pause

# ── 15 ────────────────────────────────────────────────────────────────────
stage "S11 · Graph refuses the sender"
if [[ -z "$DENIED_BY_GRAPH" ]]; then
  record S11 SKIP "no mailbox outside the ApplicationAccessPolicy given"
else
  say "Sending as $DENIED_BY_GRAPH, which graph-smtpd allows but Graph should refuse."
  note "Expected: 550 (permanent), since Graph answers 403 ErrorAccessDenied, so"
  note "clients bounce the message instead of retrying it."
  expect_reply S11 550 "$SMTP_PORT" "$DENIED_BY_GRAPH" "$(render "$MESSAGES/s1-plain.eml")" "$RCPT_A"
  note "Graph's error, from smtpd.log:"
  grep -o '"error":"[^"]*"' "$RUN_DIR/smtpd.log" | tail -n1 | sed 's/^/    /' || true
fi
pause

# ── 16 ────────────────────────────────────────────────────────────────────
stage "S14 · metrics"
WANT_SENT=9
WANT_DENIED=1
WANT_ERRORS=0
[[ -n "$DENIED_BY_GRAPH" ]] && WANT_ERRORS=1
GOT_SENT=$(metric graph_smtpd_email_total)
GOT_DENIED=$(metric graph_smtpd_email_denied_total)
GOT_ERRORS=$(metric graph_smtpd_email_errors_total)
say "graph_smtpd_email_total         ${GOT_SENT:-missing} (expected $WANT_SENT: S1–S7 plus two from S8)"
say "graph_smtpd_email_denied_total  ${GOT_DENIED:-missing} (expected $WANT_DENIED: S9)"
say "graph_smtpd_email_errors_total  ${GOT_ERRORS:-missing} (expected $WANT_ERRORS: S11)"
if [[ "$GOT_SENT" == "$WANT_SENT" && "$GOT_DENIED" == "$WANT_DENIED" && "$GOT_ERRORS" == "$WANT_ERRORS" ]]; then
  record S14 PASS "counters match"
else
  record S14 FAIL "counters differ; a failed case above also changes them"
fi
pause

# ── 17 ────────────────────────────────────────────────────────────────────
stage "S13 · unreadable secret file"
say "Starting graph-smtpd with SMTPD_SECRET_FILE pointing at a missing file."
MISSING="$RUN_DIR/no-such-secret"
set +e
env -u SMTPD_SECRET SMTPD_TENANTID="$TENANT_ID" SMTPD_CLIENTID="$CLIENT_ID" SMTPD_SECRET_FILE="$MISSING" \
  timeout 10 "$RUN_DIR/graph-smtpd" --addr "127.0.0.1:${DENY_PORT}1" > "$RUN_DIR/smtpd-missing.log" 2>&1
CODE=$?
set -e
if [[ "$CODE" == 1 ]] && grep -q "no-such-secret" "$RUN_DIR/smtpd-missing.log"; then
  record S13 PASS "exited 1, naming the file"
else
  record S13 FAIL "exit $CODE; see $RUN_DIR/smtpd-missing.log"
fi
pause

# ── 18 ────────────────────────────────────────────────────────────────────
stage "M1–M3 · graph-sendmail"
say "M1/M2: sending with graph-sendmail, From header with a display name,"
say "secret from SENDMAIL_SECRET_FILE."
set +e
env -u SENDMAIL_SECRET SENDMAIL_TENANTID="$TENANT_ID" SENDMAIL_CLIENTID="$CLIENT_ID" SENDMAIL_SECRET_FILE="$SECRET_FILE" \
  "$RUN_DIR/graph-sendmail" < "$(render "$MESSAGES/m1-display-name.eml")" > "$RUN_DIR/sendmail.log" 2>&1
CODE=$?
set -e
if [[ "$CODE" == 0 ]]; then
  record M2 PASS "sent using SENDMAIL_SECRET_FILE"
  step "In mailbox A, open \"[$TAG] M1 graph-sendmail with display name\"."
  check M1 "Did it arrive from your sender mailbox?"
else
  record M1 FAIL "exit $CODE; see $RUN_DIR/sendmail.log"
  record M2 FAIL "send failed, so the secret file is unconfirmed"
fi
say ""
say "M3: --quiet with a message graph-sendmail must reject."
set +e
OUTPUT=$(env -u SENDMAIL_SECRET SENDMAIL_TENANTID="$TENANT_ID" SENDMAIL_CLIENTID="$CLIENT_ID" SENDMAIL_SECRET_FILE="$SECRET_FILE" \
  "$RUN_DIR/graph-sendmail" --quiet < "$(render "$MESSAGES/m3-no-sender.eml")" 2>&1)
CODE=$?
set -e
if [[ "$CODE" == 1 && -z "$OUTPUT" ]]; then
  record M3 PASS "exited 1 with no output"
else
  record M3 FAIL "exit $CODE, output: ${OUTPUT:-none}"
fi
pause "Press Enter for the summary"

cleanup
finish
printf '  %sResults for %s%s\n' "$BOLD" "$TAG" "$RESET"
for r in "${RESULTS[@]}"; do printf '    %s\n' "$r"; done
printf '\n'
note "Logs and results: $RUN_DIR"
if grep -q ' FAIL ' "$RUN_DIR/results.txt"; then exit 1; fi
}

run_wizard "$@"; exit
